def register(topic,q,detail):
    for title,symbol,why,principle,use,dt,body,qa,qb in ROWS:
        topic(title,'네트워크','net/core/utils.c',symbol,why,principle,use,
              '문자열 위치, 임시 출력과 최종 출력, 성공 반환값을 나눠 추적하세요.',
              q(title+' · '+qa[0],*qa[1:]),q(title+' · '+qb[0],*qb[1:]),
              details=[detail(dt,body),detail('검토 범위','고정 Linux v6.12의 xdigit2bin·in4_pton·in6_pton·inet4_pton·inet6_pton·inet_pton_with_scope 본문을 대조했습니다. 예시는 원문의 분기를 따라 계산했으며 실제 커널 네트워크 실행 시험은 아닙니다.')])
